using Pkg
Pkg.activate(@__DIR__)
using Dates, JSON3, OrderedCollections

# stringify(dict) = "OrderedDict(\n    $(join(pairs(sort!(dict)), ",\n    "))\n)"

obj = JSON3.read(read(download("https://unpkg.com/@mdn/browser-compat-data/data.json")));

ELEMENTS = OrderedDict(
    k => setdiff(collect(keys(v)), [:__compat]) for (k,v) in obj.html.elements if length(keys(v)) > 1 && !v.__compat.status.deprecated
)
ELEMENTS_DEPRECATED = OrderedDict(
    k => setdiff(collect(keys(v)), [:__compat]) for (k,v) in obj.html.elements if length(keys(v)) > 1 && v.__compat.status.deprecated
)
GLOBAL_ATTRIBUTES = collect(keys(obj.html.global_attributes))

ELEMENTS_DEPRECATED = [k for (k,v) in obj.html.elements if v.__compat.status.deprecated]

open(joinpath(@__DIR__, "..", "src", "Reference.jl"), "w") do io
    println(io, """
    # This file was generated by deps/generate.jl at $(Dates.now())
    # Do not edit it manually
    module Reference
    using OrderedCollections: OrderedDict

    "List of attributes that can be given to any element."
    const GLOBAL_ATTRIBUTES = $GLOBAL_ATTRIBUTES

    "Mapping of element names to their attributes."
    const ELEMENTS = $ELEMENTS

    "Mapping of only deprecated element names to their attributes."
    const ELEMENTS_DEPRECATED = $ELEMENTS_DEPRECATED
    end
    """)
end



